"""Forward instrument responses for the versioned conditional RPI workflow.

This module is an owner-side native provider dependency, never an investigator
answer key. Raw records are constructed fixtures, not acquired RPI measurements.
Scientific response equations live in conditional_workflow; measurement reductions
reuse the same functions as the reviewed physical-return path.
"""
from __future__ import annotations

import csv
import hashlib
import json
import math
import tempfile
from pathlib import Path

import numpy as np

from ..measurements import (
    density_archimedes,
    microscopy_specimen_observations,
    read_sps_csv,
)

FAMILY = "rpi_conditional_workflow_v1"
SCALARS = {
    "density_g_cm3": "g/cm^3", "grain_size_nm": "nm", "grain_d90_nm": "nm",
    "coarse_number_fraction": "1", "porosity_area_fraction": "1",
}
SUPPORTED = set(SCALARS) | {"microstructure", "sps_log", "boundary_chemistry", "powder_icp_oes"}


def _canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()


def _rng(seed, identity):
    digest = hashlib.sha256(f"{seed}:{identity}".encode()).digest()
    return np.random.default_rng(int.from_bytes(digest[:8], "big"))


def _number(value, name, low=None, high=None):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    if low is not None and value < low or high is not None and value > high:
        raise ValueError(f"{name} outside conditional domain")
    return float(value)


def archimedes_response(density, mass, assumptions, *, porosity_fraction=0.):
    """Invert two weighings with explicit pore/wetting and balance assumptions.

    Connected liquid-accessible pore volume decreases displaced volume, raising
    apparent two-weighing density; trapped bubbles increase it. Neither is
    'measurement noise'. Their possible systematic effect is retained separately
    from independent input standard uncertainties.
    """
    fluid = _number(assumptions.get("fluid_density_g_cm3", .997), "fluid density", .5, 2)
    accessible = _number(assumptions.get("accessible_pore_fraction", 0), "fraction of pores accessible to fluid", 0, 1)
    pore = accessible * _number(porosity_fraction, "bulk porosity", 0, 1)
    bubble = _number(assumptions.get("bubble_volume_fraction", 0), "bubble volume fraction", 0, .2)
    dry_bias = _number(assumptions.get("dry_mass_bias_g", 0), "dry mass bias")
    immersed_bias = _number(assumptions.get("immersed_mass_bias_g", 0), "immersed mass bias")
    displaced_volume = mass / density * (1 - pore + bubble)
    raw = {"dry_mass_g": mass + dry_bias,
           "immersed_mass_g": mass - fluid * displaced_volume + immersed_bias,
           "fluid_density_g_cm3": fluid,
           "dry_mass_sd_g": assumptions.get("balance_sd_g", .0001),
           "immersed_mass_sd_g": assumptions.get("balance_sd_g", .0001),
           "fluid_density_sd_g_cm3": assumptions.get("fluid_density_sd_g_cm3", .0001)}
    reduced = density_archimedes(**raw)
    reduced.update(status="conditional_synthetic", origin="synthetic",
                   forward_measurement_assumptions={
                       "balance_sd_g": assumptions.get("balance_sd_g", .0001),
                       "fluid_density_sd_g_cm3": assumptions.get("fluid_density_sd_g_cm3", .0001),
                       "pore_access_and_wetting": "unresolved systematic effect; not estimated by two weighings",
                       "calibration_status": "assumed_for_sensitivity_not_RPI_instrument_spec"},
                   systematic_uncertainty="not included in propagated balance/fluid SD")
    return reduced


def microscopy_response(specimen_id, state, assumptions, seed, stage):
    """Construct named field features and reduce through physical-path code."""
    fields = int(_number(assumptions.get("field_count", 3), "field count", 1, 12))
    count = int(_number(assumptions.get("features_per_field", 100), "features per field", 2, 500))
    cv = _number(assumptions.get("feature_cv", .25), "feature CV", 0, 1)
    threshold = _number(assumptions.get("coarse_threshold_nm", 500), "coarse threshold", 1)
    resolved = assumptions.get("grain_boundaries_resolved", True) is True
    population = assumptions.get("selection", "systematic_sections")
    if population not in {"systematic_sections", "fine_region_only", "coarse_region_only"}:
        raise ValueError("unsupported microscopy field selection")
    fine = state["fine_region_mean_grain_size_nm"]
    coarse = state["coarse_region_mean_grain_size_nm"]
    area_fraction = state["coarse_region_area_fraction"]
    # A declared 2D equal-shape closure, not an experimentally identified
    # stereological conversion or a source-measured coarse number fraction.
    fraction = (area_fraction / coarse**2) / (area_fraction / coarse**2 + (1-area_fraction) / fine**2)
    if population == "fine_region_only":
        fraction = 0.
    elif population == "coarse_region_only":
        fraction = 1.
    sigma = math.sqrt(math.log1p(cv**2))
    records = []
    for i in range(fields):
        field_set = str(assumptions.get("field_set_id", "default"))
        rng = _rng(seed, f"microscopy:{specimen_id}:{stage}:{field_set}:{i}")
        means = np.where(rng.random(count) < fraction, coarse, fine)
        grains = rng.lognormal(np.log(means) - sigma**2 / 2, sigma).tolist() if resolved else []
        # Hypothetical field area expands to accommodate the constructed feature
        # sample at 50% solid-area coverage. It is not a fixed instrument FOV.
        feature_area_um2 = sum(math.pi*d*d/4e6 for d in grains)
        field_area = (feature_area_um2 / (.5*(1-state["porosity_fraction"]))
                      if grains else 100.)
        records.append({"specimen_id": specimen_id, "section_id": "constructed-section-"+field_set,
                        "field_id": f"constructed-field-{i+1}",
                        "source_file": f"constructed-features-{specimen_id}-{stage}-{field_set}-{i+1}.json",
                        "method": "constructed_features_not_microscopy_images",
                        "sampling_plan": population, "feature_definition": "2D_equivalent_diameter_assumption",
                        "grain_boundaries_resolved": resolved, "scale_nm_per_pixel": 1.,
                        "grain_sizes_nm": grains, "feature_ids": [f"g-{j}" for j in range(len(grains))],
                        "coarse_threshold_nm": threshold, "field_area_um2": field_area,
                        "area_basis": "constructed_FOV_for_50pct_solid_feature_coverage_not_instrument_setting",
                        "porosity_area_fraction": state["porosity_fraction"],
                        "measurement_population": population})
    reduced = microscopy_specimen_observations(records, coarse_threshold_nm=threshold)
    # These descriptors come from constructed synthetic fields, not physical
    # measurements awaiting a human quality review. Keep unavailable descriptors
    # unavailable and retain the reducer's raw records and unknown uncertainty.
    for descriptor in reduced:
        if descriptor.get("status") == "derived":
            descriptor["status"] = "conditional_synthetic"
    microstructure = {
        "raw_field_records": records, "resolved_grain_boundaries": resolved,
        "selection": population, "grain_distribution": next((r.get("distribution") for r in reduced
                                                                 if r.get("distribution")), None),
        "method": "constructed_features_not_microscopy_images",
        "measurement_assumptions": {"feature_cv": cv, "coarse_threshold_nm": threshold,
                                    "area_to_number": "equal_shape_2D_components; n proportional to area/d^2; not measured stereology",
                                    "porosity_model": "representative_isotropic_section_assumption"},
        "boundary_chemistry": {"value": None, "status": "unresolved",
                                "reason": "SEM/EDS response needs instrument and standards metadata"},
    }
    if "boundary_morphology_state" in state:
        # A categorical synthetic field description, never a numerical phase
        # fraction, calibrated BSE intensity or exposure of the private mechanism.
        description = {
            "as_sintered_reference": "bright boundary-associated contrast is concentrated at selected junction regions",
            "boundary_contrast_pattern_changed": "bright boundary-associated contrast is visible along selected grain-edge segments",
            "unresolved": "boundary-associated contrast morphology is unresolved",
        }[state["boundary_morphology_state"]]
        for record in records:
            record["boundary_contrast_description"] = description
        microstructure["boundary_morphology"] = {
            "description": description,
            "status": "constructed_qualitative_field_description",
            "method": "categorical_contrast_fixture_not_rendered_or_measured_image",
            "phase_fraction": None, "boundary_thickness_nm": None, "phase_identity": None,
            "limitations": [
                "Contrast differences do not identify a chemical phase or a causal mechanism",
                "Magnitude, kinetics and detection sensitivity are not calibrated",
                "Comparison requires an actually acquired as-sintered reference and compatible fields",
                "This record describes this stage only and does not assert an observed before/after change",
                "No numerical boundary response is specified for other annealing histories",
                "No magnetic-property inference follows from this descriptor",
            ],
        }
    return {r["quantity"]: r for r in reduced}, microstructure


def sps_response(condition, state, assumptions):
    """Mass-conserving axial shrinkage plus an explicit tooling displacement term.

    The trace is a normalized constructed sensor export. Densification follows the same Arrhenius closure through ramp, dwell and
    conditional cooldown; this is not a calibrated displacement kinetic model.
    """
    from .conditional_workflow import thermal_dose
    peak = condition["temperature_c"]
    ramp = condition["heating_rate_c_min"]
    hold = condition["hold_time_s"]
    p = state["parameters"]
    default_cooling = p["argon_quench_rate_c_min"] if condition.get("cooling_mode") == "argon_quench" else p["furnace_cooling_rate_c_min"]
    cooling = condition.get("sps_cooling_rate_c_min", default_cooling)
    if cooling is None:
        raise ValueError("a full synthetic SPS trace requires an explicit conditional cooldown")
    ramp_s, cool_s = (peak-25)/ramp*60, (peak-25)/cooling*60
    mass = condition["mass_g"]
    diameter = _number(condition.get("diameter_mm", 10), "conditional diameter", 1, 50)
    green_density = p["solid_density_g_cm3"] * p["initial_relative_density"]
    area = math.pi * (diameter / 20)**2
    tooling = _number(assumptions.get("tooling_displacement_mm_per_c", .001), "tooling coefficient", -.01, .01)
    q, offset = p["density_activation_energy_kj_mol"], p["temperature_offset_c"]
    times = np.unique(np.concatenate((np.linspace(0, ramp_s, 61),
        np.linspace(ramp_s, ramp_s+hold, 21), np.linspace(ramp_s+hold, ramp_s+hold+cool_s, 61))))
    temps, doses = [], []
    dwell_dose = thermal_dose(peak, ramp, hold, q, offset_c=offset)
    cool_dose = thermal_dose(peak, cooling, 0, q, offset_c=offset)
    for t in times:
        if t <= ramp_s:
            temp = 25+t*ramp/60
            dose = thermal_dose(float(temp), ramp, 0, q, offset_c=offset)
        elif t <= ramp_s+hold:
            temp = peak
            dose = thermal_dose(peak, ramp, float(t-ramp_s), q, offset_c=offset)
        else:
            temp = max(25., peak-(t-ramp_s-hold)*cooling/60)
            dose = dwell_dose+cool_dose-thermal_dose(float(temp), cooling, 0, q, offset_c=offset)
        temps.append(float(temp))
        doses.append(dose)
    ceiling = p["solid_density_g_cm3"]*p["limiting_relative_density"]
    rate = (p["density_rate_per_s_at_750"]*p["density_transfer_multiplier"]
            *(condition["pressure_mpa"]/50)**p["pressure_exponent"]
            *(ramp/100)**p["ramp_contact_exponent"])
    rho = [ceiling-(ceiling-green_density)*math.exp(-rate*dose) for dose in doses]
    displacement = [10*mass/area*(1/green_density-1/r)+tooling*(t-25)
                    for r, t in zip(rho, temps)]
    with tempfile.TemporaryDirectory(prefix="ndfeb-normalized-sps-") as directory:
        path = Path(directory) / "constructed.csv"
        with path.open("w", newline="") as handle:
            writer = csv.writer(handle)
            writer.writerow(["time_s", "temperature_C", "pressure_MPa", "displacement_mm"])
            writer.writerows(zip(times, temps, [condition["pressure_mpa"]]*len(times), displacement))
        reduced = read_sps_csv(path)
    return {"time_s": times.tolist(), "temperature_c": temps,
            "pressure_mpa": [condition["pressure_mpa"]]*len(times), "displacement_mm": displacement,
            "reduction": reduced, "method": "constructed_normalized_sensor_trace",
            "limits": ["Tooling term not independently removed", "Sensor temperature need not be powder temperature",
                       "Mass, die geometry, green density and kinetic trace closure are conditional assumptions",
                       "No SPS electrical energy or power measurement"]}


def _legacy_default_anneal_history(previous, prior, parameters):
    """Compatibility only for replaying already-recorded accepted anneal history.

New requests never use this helper. An old `steps` alias is accepted only when
its complete contents and top-level controls identify the exact default 900 C /
7200 s then 520 C / 7200 s history. A nondefault old alias remains unsupported;
it cannot be interpreted as evidence that its requested controls were executed.
The input is copied and the caller reports this compatibility in provenance.
    """
    expected = [{"temperature_c": 900, "hold_time_s": 7200},
                {"temperature_c": 520, "hold_time_s": 7200}]
    rate = parameters.get("anneal_heating_rate_c_min", 10.)
    if (previous.get("operation") != "anneal" or "steps" not in previous
        or "anneal_steps" in previous or previous["steps"] != expected
        or previous.get("temperature_c") != 900 or previous.get("hold_time_s") != 7200
        or previous.get("heating_rate_c_min", rate) != rate
        or previous.get("pressure_mpa", 0) != 0
        or previous.get("output_stage") != "after_second_anneal"
        or prior is None or prior["process_stage"] != "as_sintered"):
        return previous, False
    normalized = json.loads(json.dumps(previous))
    normalized.pop("steps")
    normalized["anneal_steps"] = [
        {**step, "stage": stage, "heating_rate_c_min": rate}
        for step, stage in zip(expected, ("after_first_anneal", "after_second_anneal"), strict=True)
    ]
    return normalized, True


MICROSCOPY_SELECTION_KEYS = frozenset({"field_count", "features_per_field", "field_set_id", "selection", "coarse_threshold_nm"})


def validate_workflow_request_controls(request: dict) -> None:
    """World-free validation of NEW request controls; raises ValueError.

This performs no fit, numerical simulation, ledger mutation or private-world
lookup. Prior history is bound and reconstructed separately by the provider;
legacy-history compatibility never grants aliases to a newly submitted request.
Material consumption controls belong directly on each specimen, alongside
conditions. Historical conditions are not reinterpreted as material outcomes.
    """
    from .conditional_workflow import validate_anneal_condition
    operation = request.get("operation", "manufacture")
    if operation not in {"manufacture", "anneal", "measure"}:
        raise ValueError("unsupported workflow operation")
    misplaced_sampling = sorted(set(request) & (MICROSCOPY_SELECTION_KEYS | {"measurement_context"}))
    if misplaced_sampling:
        raise ValueError(
            f"Sampling controls {', '.join(misplaced_sampling)} belong in each "
            "specimen.conditions.measurement_context object, not the request; "
            "use conditions.measurement_context={field_count:5, features_per_field:100, coarse_threshold_nm:1000}"
        )
    material_controls = {"consumed_mass_g", "destructive", "specimen_available"}
    misplaced = sorted(set(request) & material_controls)
    if misplaced:
        raise ValueError(
            f"Material controls {', '.join(misplaced)} belong directly on each specimen, "
            "not the request; use specimen.consumed_mass_g, specimen.destructive and "
            "specimen.specimen_available"
        )
    process_controls = {
        "steps", "anneal_steps", "temperature_c", "hold_time_s", "heating_rate_c_min",
        "pressure_mpa", "cooling_rate_c_min", "cooling_mode", "post_treatment",
    }
    if operation == "anneal" and set(request) & process_controls:
        raise ValueError("Anneal controls belong in each specimen.conditions; use canonical anneal_steps")
    for specimen in request.get("specimens", []):
        condition = specimen.get("conditions")
        if not isinstance(condition, dict):
            raise ValueError("Each specimen requires a conditions object")  # noqa: TRY004 - public validation contract
        if "measurements" in condition:
            raise ValueError(
                f"{specimen.get('specimen_id', 'specimen')}: measurements belongs at "
                "request.measurements or specimen.measurements, not specimen.conditions.measurements"
            )
        misplaced_sampling = sorted((set(specimen) & (MICROSCOPY_SELECTION_KEYS | {"measurement_context"}))
                                    | (set(condition) & MICROSCOPY_SELECTION_KEYS))
        if misplaced_sampling:
            raise ValueError(
                f"Sampling controls {', '.join(misplaced_sampling)} belong in "
                "specimen.conditions.measurement_context, not flat specimen or conditions keys; "
                "use conditions.measurement_context={field_count:5, features_per_field:100, coarse_threshold_nm:1000}"
            )
        misplaced = sorted(set(condition) & material_controls)
        if misplaced:
            raise ValueError(
                f"Material controls {', '.join(misplaced)} belong directly on the specimen, "
                "not specimen.conditions; use specimen.consumed_mass_g, specimen.destructive "
                "and specimen.specimen_available"
            )
        if condition.get("operation", operation) != operation:
            raise ValueError("specimen conditions.operation conflicts with the requested operation")
        if ("output_stage" in condition and "output_stage" in request
            and condition["output_stage"] != request["output_stage"]):
            raise ValueError("specimen conditions.output_stage conflicts with the requested output_stage")
        if operation == "anneal":
            if set(specimen) & process_controls:
                raise ValueError("Anneal controls belong in specimen.conditions; use canonical anneal_steps")
            input_stage = request.get("input_stage", specimen.get("input_stage", "as_sintered"))
            if specimen.get("input_stage", input_stage) != input_stage:
                raise ValueError("specimen.input_stage conflicts with requested input_stage")
            output_stage = request.get("output_stage", condition.get("output_stage"))
            validate_anneal_condition(condition, input_stage=input_stage, output_stage=output_stage)


def simulate_workflow(request, world_config, seed):
    """Native response entry point for manufacture, existing-body anneal and measure."""
    from .conditional_workflow import conditional_forecast
    if world_config.get("family") != FAMILY or request.get("origin") != "synthetic":
        raise ValueError("conditional workflow requires an explicit synthetic family and request")
    validate_workflow_request_controls(request)
    operation = request.get("operation", "manufacture")
    hypothesis = world_config["hypothesis"]
    measurement = world_config.get("measurement", {})
    observations, delivered, outcomes = [], {}, {}
    legacy_history_compatibility = []
    preparation_outcomes = {}
    for preparation in request.get("preparations", []):
        planned = preparation["conditions"]
        expected = {"method": "sealed_quartz_degassing", "temperature_c": 600., "hold_time_s": 900.,
                    "heating_rate_c_min": 5., "cooling_mode": "furnace_cooling"}
        if any(planned.get(k) != v for k, v in expected.items()):
            raise ValueError("this conditional family implements only the accepted preparation; changed preparation needs new model support")
        preparation_outcomes[preparation["preparation_id"]] = {
            "executed": True, "conditions": planned, "origin": "synthetic",
            "status": "conditional_execution_not_physical_preparation"}
    request_hash = hashlib.sha256(_canonical(request)).hexdigest()
    for specimen in request["specimens"]:
        sid, prep, cycle = (specimen[k] for k in ("specimen_id", "preparation_id", "cycle_id"))
        condition = json.loads(json.dumps(specimen["conditions"]))
        if condition.get("operation", operation) != operation:
            raise ValueError("specimen conditions.operation conflicts with the requested operation")
        if ("output_stage" in condition and "output_stage" in request
            and condition["output_stage"] != request["output_stage"]):
            raise ValueError("specimen conditions.output_stage conflicts with the requested output_stage")
        condition.update(operation=operation, output_stage=request.get("output_stage", "as_sintered"))
        selection_context = condition.get("measurement_context", {})
        allowed_context = MICROSCOPY_SELECTION_KEYS
        if not isinstance(selection_context, dict) or set(selection_context)-allowed_context:
            raise ValueError("measurement_context may select field counts/set/population/threshold; it cannot change owner instrument errors")
        specimen_measurement = {**measurement, **selection_context}
        parameters = dict(world_config.get("parameters", {}))
        parameters.update(world_config.get("preparation_parameters", {}).get(prep, {}))
        prior = None
        for index, previous in enumerate(specimen.get("prior_processing_conditions", [])):
            if (previous.get("operation") == "anneal" and "anneal_steps" in previous
                and "steps" in previous and previous["steps"] is None):
                # Campaign.receive retains absent requested keys as null. Only
                # recorded history with authoritative canonical steps may drop
                # this null placeholder; new requests still reject every alias.
                previous = {key: value for key, value in previous.items() if key != "steps"}
                legacy_history_compatibility.append({"specimen_id": sid, "history_index": index,
                    "rule": "correction_omitted_legacy_alias",
                    "original_request_unchanged": True})
            reconstructed, compatibility_used = _legacy_default_anneal_history(previous, prior, parameters)
            prior_forecast = conditional_forecast(
                reconstructed, hypothesis=hypothesis, parameters=parameters, prior_state=prior,
                anneal_response=world_config.get("anneal_response"))
            prior = prior_forecast["latent_state"]
            if compatibility_used:
                legacy_history_compatibility.append({"specimen_id": sid, "history_index": index,
                    "rule": "verified_exact_legacy_900c_7200s_then_520c_7200s_alias_only",
                    "original_request_unchanged": True})
        if operation != "manufacture" and prior is None:
            raise ValueError("existing-specimen operation needs bound prior_processing_conditions")
        if (prior is not None and request.get("input_stage", prior["process_stage"]) != prior["process_stage"]):
            raise ValueError("request.input_stage conflicts with executed prior history")
        if (prior is not None and specimen.get("input_stage", prior["process_stage"]) != prior["process_stage"]):
            raise ValueError("specimen.input_stage conflicts with executed prior history")
        if operation == "measure":
            state = prior
        else:
            result = conditional_forecast(
                condition, hypothesis=hypothesis, parameters=parameters, prior_state=prior,
                anneal_response=world_config.get("anneal_response"))
            state = result["latent_state"]
        stage = request.get("output_stage", "as_sintered" if operation == "manufacture" else condition.get("process_stage"))
        if not stage:
            raise ValueError("workflow operation must identify resulting stage")
        if stage != state["process_stage"]:
            raise ValueError("requested output_stage differs from executed processing stage")
        selection = specimen.get("measurements", request.get("measurements", ["density_g_cm3"]))
        if not selection or len(selection) != len(set(selection)) or set(selection)-SUPPORTED:
            raise ValueError("unsupported, empty or duplicated measurement selection")
        if "sps_log" in selection and operation != "manufacture":
            raise ValueError("an anneal or repeat measurement cannot produce a new SPS trace")
        identity = {"specimen_id": sid, "lot_id": request["lot_id"], "preparation_id": prep,
                    "cycle_id": cycle, "origin": "synthetic", "process_stage": stage}
        actual_condition = dict(condition)
        if operation == "anneal":
            public_controls = ("stage", "temperature_c", "hold_time_s", "heating_rate_c_min",
                               "pressure_mpa", "cooling_rate_c_min")
            executed = [{key: step[key] for key in public_controls}
                        for step in state["history"][len(prior["history"]):]]
            actual_condition["anneal_steps"] = executed
            for key in ("temperature_c", "hold_time_s", "heating_rate_c_min", "pressure_mpa"):
                actual_condition[key] = executed[0][key]
            if "post_treatment" in condition:
                actual_condition["requested_post_treatment_label"] = condition["post_treatment"]
            actual_condition["post_treatment"] = "anneal_" + "_".join(
                f"{step['temperature_c']:g}c_{step['hold_time_s']:g}s" for step in executed)
            actual_condition["execution_control_status"] = "canonical_controls_from_executed_history"
        delivered[sid] = {**actual_condition, **identity, "delivery_status": "declared_conditional_execution"}
        records = {}
        if "density_g_cm3" in selection:
            mass = condition.get("mass_g", specimen.get("remaining_mass_g"))
            mass = _number(mass, "conditional specimen mass", .01, 25)
            records["density_g_cm3"] = archimedes_response(state["density_g_cm3"], mass, specimen_measurement,
                                                          porosity_fraction=state["porosity_fraction"])
        if set(selection) & ((set(SCALARS)-{"density_g_cm3"}) | {"microstructure"}):
            descriptors, micro = microscopy_response(sid, state, specimen_measurement, seed, stage)
            raw_fields = micro["raw_field_records"]
            feature_counts = [len(record["grain_sizes_nm"]) for record in raw_fields]
            # Delivered sampling is derived from constructed raw records, never
            # copied from requested aliases or unexecuted defaults. Unresolved
            # grain boundaries honestly deliver zero measured grain features.
            delivered[sid]["measurement_context"] = {
                "field_count": len(raw_fields),
                "features_per_field": feature_counts[0] if len(set(feature_counts)) == 1 else None,
                "field_set_id": str(specimen_measurement.get("field_set_id", "default")),
                "selection": micro["selection"],
                "coarse_threshold_nm": micro["measurement_assumptions"]["coarse_threshold_nm"],
            }
            records.update(descriptors)
            records["microstructure"] = {"value": micro, "unit": "mixed", "method": micro["method"]}
        if "sps_log" in selection:
            records["sps_log"] = {"value": sps_response(condition, state, measurement), "unit": "mixed"}
        for quantity in selection:
            rec = records.get(quantity, {"value": None, "unit": SCALARS.get(quantity, "mixed"),
                        "status": "unavailable", "reason": "No numerical response without appropriate sampling, standards and instrument model; request the raw record and method metadata"})
            observations.append({**rec, **identity, "observation_id": f"{request_hash[:16]}:{sid}:{quantity}",
                                 "quantity": quantity, "status": rec.get("status", "conditional_synthetic"),
                                 "uncertainty": rec.get("uncertainty"),
                                 "evidence_scope": "conditional_computation_not_RPI_measurement"})
        consumed = _number(specimen.get("consumed_mass_g", 0), "consumed mass", 0)
        available_mass = condition.get("mass_g", specimen.get("remaining_mass_g"))
        if available_mass is not None:
            available_mass = _number(available_mass, "available mass", 0, 25)
            if consumed > available_mass:
                raise ValueError("declared consumption exceeds conditional specimen mass")
        remaining = None if available_mass is None else available_mass-consumed
        outcomes[sid] = {"executed": True, "stage": stage, "consumed_mass_g": consumed,
                         "destructive": specimen.get("destructive", False),
                         "remaining_mass_g": remaining,
                         "specimen_available": specimen.get("specimen_available", remaining != 0),
                         "operation": operation, "preparation_execution_status": "conditional"}
    delivery = {"delivery_id": "conditional-"+request_hash[:20], "origin": "synthetic", "complete": True,
            "observations": observations, "delivered_conditions": delivered,
            "specimen_outcomes": outcomes, "preparation_outcomes": preparation_outcomes,
            "manufactured_specimen_ids": list(delivered) if operation == "manufacture" else [],
            "simulation_accounting": {"operation": operation,
                "new_manufactured_count": len(delivered) if operation == "manufacture" else 0,
                "status": "conditional_not_physical_throughput"},
            "provenance": {"evidence_class": "conditional_synthetic", "model_version": FAMILY,
                           "physical_execution": False,
                           "request_world_seed_sha256": hashlib.sha256(_canonical(
                               {"request": request, "world": world_config, "seed": seed})).hexdigest()}}
    if legacy_history_compatibility:
        delivery["provenance"]["legacy_default_anneal_history_compatibility"] = legacy_history_compatibility
    return delivery
